function bounds(im){let left=im.width,right=-1,count=0;for(let y=0;y<im.height;y++)for(let x=0;x<im.width;x++)if(im.data[(y*im.width+x)*4+3]){left=Math.min(left,x);right=Math.max(right,x);count++;}return {left,right,count};}
function headBounds(im){const seen=new Set(),parts=[];for(let k=0;k<im.width*im.height;k++){if(seen.has(k)||!im.data[k*4+3])continue;const q=[k],xs=[];seen.add(k);for(let i=0;i<q.length;i++){const at=q[i],x=at%im.width,y=Math.floor(at/im.width);xs.push(x);for(const [nx,ny]of [[x-1,y],[x+1,y],[x,y-1],[x,y+1]]){if(nx<0||ny<0||nx>=im.width||ny>=im.height)continue;const j=ny*im.width+nx;if(!seen.has(j)&&im.data[j*4+3]){seen.add(j);q.push(j);}}}parts.push({count:q.length,left:Math.min(...xs),right:Math.max(...xs)});}assert(parts.length);return parts.sort((a,b)=>b.count-a.count)[0];}
function visible(p,l){if(!l.visible||l.isGroup)return false;let parent=l.parent;const seen=new Set();while(parent!=null){if(seen.has(parent))return false;seen.add(parent);if(!p.layers[parent]?.visible)return false;parent=p.layers[parent].parent;}return true;}
